import requests
import json

# Test API with proper user-agent
url = 'https://en.wikipedia.org/w/api.php'
headers = {
    'User-Agent': 'Twitter-Citation-Counter/1.0 (https://github.com/example; mailto:example@example.com)'
}
params = {
    'action': 'query',
    'prop': 'info',
    'titles': 'Main Page',
    'format': 'json'
}

try:
    response = requests.get(url, params=params, headers=headers)
    print(f'Status code: {response.status_code}')
    if response.status_code == 200:
        data = response.json()
        print('API is working')

        # Now try to get August 1 revisions
        params['prop'] = 'revisions'
        params['titles'] = 'August 1'
        params['rvlimit'] = 50
        params['rvstart'] = '2023-06-30'
        params['rvend'] = '2023-06-01'

        response = requests.get(url, params=params, headers=headers)
        data = response.json()
        pages = data.get('query', {}).get('pages', {})
        for page_id, page_data in pages.items():
            revisions = page_data.get('revisions', [])
            print(f'August 1 revisions from June 2023:')
            for rev in revisions[:3]:
                print(f'  ID: {rev[\"revid\"]}, Timestamp: {rev[\"timestamp\"]}')
            if revisions:
                print(f'  First June 2023 revision ID: {revisions[0][\"revid\"]}')
            else:
                print('  No June 2023 revisions found')
    else:
        print(f'API returned error: {response.text[:200]}')
except Exception as e:
    print(f'Error: {e}')
""}

