import requests
import json

# Function to get June 2023 revision ID for an August day
def get_june_2023_revision(day):
    url = 'https://en.wikipedia.org/w/api.php'
    headers = {
        'User-Agent': 'Twitter-Citation-Counter/1.0 (https://github.com/example; mailto:example@example.com)'
    }
    params = {
        'action': 'query',
        'prop': 'revisions',
        'titles': f'August {day}',
        'rvlimit': 1,
        'rvstart': '2023-07-01T00:00:00Z',
        'rvend': '2023-06-01T00:00:00Z',
        'format': 'json'
    }

    try:
        response = requests.get(url, params=params, headers=headers)
        data = response.json()
        pages = data.get('query', {}).get('pages', {})
        for page_id, page_data in pages.items():
            revisions = page_data.get('revisions', [])
            if revisions:
                return revisions[0]['revid'], revisions[0]['timestamp']
            else:
                return None, None
    except Exception as e:
        print(f'Error getting revision for August {day}: {e}')
        return None, None

# Get revision IDs for all August days
print('Getting revision IDs for all August days from June 2023:')
revision_data = {}

for day in range(1, 32):
    revid, timestamp = get_june_2023_revision(day)
    if revid:
        revision_data[day] = {'revid': revid, 'timestamp': timestamp}
        print(f'  August {day}: ID {revid} ({timestamp})')
    else:
        print(f'  August {day}: No June 2023 revision found')
        revision_data[day] = None

print(f'\nFound revisions for {len([d for d in revision_data if revision_data[d]])} out of 31 days')
""}

